import string

def word_frequency(text: str) -> dict[str, int]:
    frequency = {}
    if not text:
        return frequency

    words = text.lower().split()
    for word in words:
        cleaned_word = word.strip(string.punctuation)
        if cleaned_word:
            frequency[cleaned_word] = frequency.get(cleaned_word, 0) + 1

    return frequency
